def compute(vars):
    interest_2019 = vars["v1"]
    interest_2018 = vars["v2"]

    if interest_2019 > interest_2018:
        value = 2019
    elif interest_2018 > interest_2019:
        value = 2018
    else:
        value = None

    return {
        "value": value,
        "trace": {
            "interest_received_2019": interest_2019,
            "interest_received_2018": interest_2018,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
